/**
 * Disambiguation Modal for Artopath Work Detail Page
 *
 * USE CASE: User reports "wrong work" generated by AI search
 * INTENTION: Provide 3 similar work choices to let user pick correct match
 * VISION: "Second Art Brain" must identify the right work to build accurate knowledge
 * TRADE-OFF: Modal approach (vs inline) for focused disambiguation; limited to 3 choices for clarity
 *
 * Flow:
 * 1. User clicks "Wrong Work?" button
 * 2. Modal shows 3 similar works from search API
 * 3. If none match, show follow-up form for more details
 * 4. User selection triggers navigation to correct work or new search
 */

// ============================================
// DISAMBIGUATION MODULE
// ============================================

(function() {
  'use strict';

  const DEBUG = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1';

  /**
   * DisambiguationModal class
   * Manages the wrong-work disambiguation flow
   */
  class DisambiguationModal {
    constructor() {
      this.modalEl = null;
      this.originalQuery = '';
      this.similarWorks = [];
      this.currentWorkId = null;
      this.onSelectCallback = null;

      // Bind methods
      this.handleBackdropClick = this.handleBackdropClick.bind(this);
      this.handleKeyDown = this.handleKeyDown.bind(this);
    }

    /**
     * Initialize the modal (create DOM if not exists)
     */
    init() {
      if (this.modalEl) return;

      this.modalEl = document.createElement('div');
      this.modalEl.id = 'disambiguationModal';
      this.modalEl.className = 'disambiguation-modal';
      this.modalEl.setAttribute('role', 'dialog');
      this.modalEl.setAttribute('aria-modal', 'true');
      this.modalEl.setAttribute('aria-labelledby', 'disambiguationTitle');
      this.modalEl.innerHTML = this._createModalHTML();

      document.body.appendChild(this.modalEl);

      // Attach event listeners
      this.modalEl.addEventListener('click', this.handleBackdropClick);
      document.addEventListener('keydown', this.handleKeyDown);

      if (DEBUG) console.log('[Disambiguation] Modal initialized');
    }

    /**
     * Create modal HTML structure
     * @private
     */
    _createModalHTML() {
      return `
        <div class="disambiguation-modal-content" onclick="event.stopPropagation()">
          <div class="disambiguation-modal-header">
            <h2 id="disambiguationTitle" class="disambiguation-modal-title">Did you mean one of these?</h2>
            <button class="disambiguation-modal-close" onclick="window.DisambiguationModal.close()" aria-label="Close">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                <line x1="18" y1="6" x2="6" y2="18"></line>
                <line x1="6" y1="6" x2="18" y2="18"></line>
              </svg>
            </button>
          </div>
          <div class="disambiguation-body">
            <!-- Choices view (initial) -->
            <div id="disambiguationChoices" class="disambiguation-choices">
              <p class="disambiguation-hint">We found similar works. Select the correct one:</p>
              <div id="disambiguationList" class="disambiguation-list" role="radiogroup" aria-label="Similar works">
                <!-- Work choices populated dynamically -->
              </div>
              <button id="disambiguationNoneBtn" class="disambiguation-none-btn" onclick="window.DisambiguationModal.showFollowUpForm()">
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="18" height="18">
                  <circle cx="12" cy="12" r="10"/>
                  <path d="M12 16v-4M12 8h.01"/>
                </svg>
                None of these - provide more info
              </button>
            </div>
            <!-- Follow-up form (shown when none match) -->
            <div id="disambiguationForm" class="disambiguation-form" style="display: none;">
              <p class="disambiguation-hint">Help us find the right work:</p>
              <form id="disambiguationSearchForm" onsubmit="window.DisambiguationModal.handleFormSubmit(event)">
                <div class="disambiguation-form-group">
                  <label for="disambiguationTitle">Title</label>
                  <input type="text" id="disambiguationTitleInput" name="title" placeholder="e.g., Spirited Away" required>
                </div>
                <div class="disambiguation-form-row">
                  <div class="disambiguation-form-group">
                    <label for="disambiguationYear">Year</label>
                    <input type="text" id="disambiguationYearInput" name="year" placeholder="e.g., 2001" pattern="[0-9]{4}" maxlength="4">
                  </div>
                  <div class="disambiguation-form-group">
                    <label for="disambiguationType">Type</label>
                    <div class="disambiguation-type-options" role="radiogroup" aria-label="Work type">
                      <label class="disambiguation-type-option">
                        <input type="radio" name="workType" value="film">
                        <span>Film</span>
                      </label>
                      <label class="disambiguation-type-option">
                        <input type="radio" name="workType" value="artwork">
                        <span>Artwork</span>
                      </label>
                      <label class="disambiguation-type-option">
                        <input type="radio" name="workType" value="tv">
                        <span>TV</span>
                      </label>
                      <label class="disambiguation-type-option">
                        <input type="radio" name="workType" value="other">
                        <span>Other</span>
                      </label>
                    </div>
                  </div>
                </div>
                <div class="disambiguation-form-group">
                  <label for="disambiguationCreator">Director / Artist</label>
                  <input type="text" id="disambiguationCreatorInput" name="creator" placeholder="e.g., Hayao Miyazaki">
                </div>
                <div class="disambiguation-form-actions">
                  <button type="button" class="disambiguation-back-btn" onclick="window.DisambiguationModal.showChoices()">
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="16" height="16">
                      <path d="M19 12H5M12 19l-7-7 7-7"/>
                    </svg>
                    Back
                  </button>
                  <button type="submit" class="disambiguation-search-btn" id="disambiguationSearchBtn">
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="16" height="16">
                      <circle cx="11" cy="11" r="8"/>
                      <path d="m21 21-4.35-4.35"/>
                    </svg>
                    Search Again
                  </button>
                </div>
              </form>
            </div>
            <!-- Loading state -->
            <div id="disambiguationLoading" class="disambiguation-loading" style="display: none;">
              <div class="disambiguation-spinner"></div>
              <p>Searching for similar works...</p>
            </div>
          </div>
        </div>
      `;
    }

    /**
     * Show the modal with similar works
     * @param {string} originalQuery - The original search query that was wrong
     * @param {Array} similarWorks - Array of similar work objects
     * @param {Object} options - Additional options { currentWorkId, onSelect }
     */
    show(originalQuery, similarWorks, options = {}) {
      this.init();

      this.originalQuery = originalQuery;
      this.similarWorks = similarWorks.slice(0, 3); // Max 3 choices
      this.currentWorkId = options.currentWorkId || null;
      this.onSelectCallback = options.onSelect || null;

      // Render choices
      this._renderChoices();

      // Show modal
      this.modalEl.classList.add('active');
      document.body.style.overflow = 'hidden';

      // Focus first choice
      setTimeout(() => {
        const firstChoice = this.modalEl.querySelector('.disambiguation-choice');
        if (firstChoice) firstChoice.focus();
      }, 100);

      if (DEBUG) console.log('[Disambiguation] Modal shown with', this.similarWorks.length, 'choices');
    }

    /**
     * Render work choices in the list
     * @private
     */
    _renderChoices() {
      const listEl = document.getElementById('disambiguationList');
      const choicesEl = document.getElementById('disambiguationChoices');
      const formEl = document.getElementById('disambiguationForm');
      const loadingEl = document.getElementById('disambiguationLoading');

      // Show choices, hide form and loading
      choicesEl.style.display = 'block';
      formEl.style.display = 'none';
      loadingEl.style.display = 'none';

      if (this.similarWorks.length === 0) {
        // No similar works found - show form directly
        this.showFollowUpForm();
        return;
      }

      listEl.innerHTML = this.similarWorks.map((work, index) => {
        const title = this._escapeHtml(work.title_display || work.title || 'Untitled');
        const year = work.date_created_year || work.year || '';
        const creator = this._getCreator(work);
        const type = this._getTypeLabel(work.type || work.work_type);
        const thumbnail = work.image || work.poster || '';
        const workId = work.id || work.slug || '';

        return `
          <button
            class="disambiguation-choice"
            data-work-id="${this._escapeHtml(workId)}"
            data-work-index="${index}"
            onclick="window.DisambiguationModal.selectWork(${index})"
            role="radio"
            aria-checked="false"
          >
            <div class="disambiguation-choice-radio">
              <span class="radio-dot"></span>
            </div>
            <div class="disambiguation-choice-thumb">
              ${thumbnail ? `<img src="${this._escapeHtml(thumbnail)}" alt="" loading="lazy" onerror="this.style.display='none'">` : ''}
              <div class="disambiguation-choice-thumb-placeholder">
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" width="24" height="24">
                  <rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect>
                  <circle cx="8.5" cy="8.5" r="1.5"></circle>
                  <polyline points="21 15 16 10 5 21"></polyline>
                </svg>
              </div>
            </div>
            <div class="disambiguation-choice-info">
              <div class="disambiguation-choice-title">${title}</div>
              <div class="disambiguation-choice-meta">
                ${creator ? `<span class="disambiguation-creator">${this._escapeHtml(creator)}</span>` : ''}
                ${year ? `<span class="disambiguation-year">${year}</span>` : ''}
                ${type ? `<span class="disambiguation-type chip-type">${type}</span>` : ''}
              </div>
            </div>
          </button>
        `;
      }).join('');
    }

    /**
     * Show the follow-up form for more details
     */
    showFollowUpForm() {
      const choicesEl = document.getElementById('disambiguationChoices');
      const formEl = document.getElementById('disambiguationForm');
      const loadingEl = document.getElementById('disambiguationLoading');

      choicesEl.style.display = 'none';
      formEl.style.display = 'block';
      loadingEl.style.display = 'none';

      // Pre-fill title from original query
      const titleInput = document.getElementById('disambiguationTitleInput');
      if (titleInput && this.originalQuery) {
        titleInput.value = this.originalQuery;
      }

      // Focus title input
      setTimeout(() => {
        titleInput?.focus();
      }, 100);

      if (DEBUG) console.log('[Disambiguation] Showing follow-up form');
    }

    /**
     * Show the choices view (back from form)
     */
    showChoices() {
      const choicesEl = document.getElementById('disambiguationChoices');
      const formEl = document.getElementById('disambiguationForm');

      choicesEl.style.display = 'block';
      formEl.style.display = 'none';

      if (DEBUG) console.log('[Disambiguation] Back to choices');
    }

    /**
     * Show loading state
     */
    showLoading() {
      const choicesEl = document.getElementById('disambiguationChoices');
      const formEl = document.getElementById('disambiguationForm');
      const loadingEl = document.getElementById('disambiguationLoading');

      choicesEl.style.display = 'none';
      formEl.style.display = 'none';
      loadingEl.style.display = 'flex';
    }

    /**
     * Handle work selection
     * @param {number} index - Index of selected work
     */
    selectWork(index) {
      const work = this.similarWorks[index];
      if (!work) return;

      if (DEBUG) console.log('[Disambiguation] Selected work:', work.title_display || work.title);

      // Call callback if provided
      if (this.onSelectCallback) {
        this.onSelectCallback(work);
      }

      // Close modal and navigate to the selected work
      this.close();

      // Navigate to the work detail page
      const workId = work.id || work.slug;
      if (workId) {
        window.location.href = `work-detail.html?id=${encodeURIComponent(workId)}`;
      }
    }

    /**
     * Handle form submission for refined search
     * @param {Event} event - Form submit event
     */
    handleFormSubmit(event) {
      event.preventDefault();

      const form = event.target;
      const formData = new FormData(form);

      const searchParams = {
        title: formData.get('title') || '',
        year: formData.get('year') || '',
        type: formData.get('workType') || '',
        creator: formData.get('creator') || ''
      };

      if (!searchParams.title.trim()) {
        // Focus title input
        document.getElementById('disambiguationTitleInput')?.focus();
        return;
      }

      if (DEBUG) console.log('[Disambiguation] Form submitted:', searchParams);

      // Build search query
      let query = searchParams.title;
      if (searchParams.year) query += ` ${searchParams.year}`;
      if (searchParams.creator) query += ` ${searchParams.creator}`;

      // Close modal and navigate to search
      this.close();

      // Navigate to work-detail with stream=true for new search
      const encodedQuery = encodeURIComponent(query);
      window.location.href = `work-detail.html?search=${encodedQuery}&stream=true`;
    }

    /**
     * Close the modal
     */
    close() {
      if (this.modalEl) {
        this.modalEl.classList.remove('active');
        document.body.style.overflow = '';
      }

      // Reset form
      const form = document.getElementById('disambiguationSearchForm');
      if (form) form.reset();

      if (DEBUG) console.log('[Disambiguation] Modal closed');
    }

    /**
     * Handle backdrop click (close on click outside)
     * @param {Event} event
     */
    handleBackdropClick(event) {
      if (event.target === this.modalEl) {
        this.close();
      }
    }

    /**
     * Handle keyboard events (Escape to close)
     * @param {KeyboardEvent} event
     */
    handleKeyDown(event) {
      if (event.key === 'Escape' && this.modalEl?.classList.contains('active')) {
        this.close();
      }
    }

    /**
     * Escape HTML to prevent XSS
     * @param {string} str
     * @returns {string}
     * @private
     */
    _escapeHtml(str) {
      if (!str) return '';
      const div = document.createElement('div');
      div.textContent = str;
      return div.innerHTML;
    }

    /**
     * Get creator name from work object
     * @param {Object} work
     * @returns {string}
     * @private
     */
    _getCreator(work) {
      // Try person_roles first (canonical format)
      if (work.person_roles && Array.isArray(work.person_roles)) {
        const creatorRole = work.person_roles.find(r =>
          ['artist', 'director', 'creator'].includes(r.role_type)
        );
        if (creatorRole?.person?.name_display) {
          return creatorRole.person.name_display;
        }
      }
      // Fallback to legacy fields
      return work.creator || work.director || work.artist || '';
    }

    /**
     * Get display label for work type
     * @param {string} type
     * @returns {string}
     * @private
     */
    _getTypeLabel(type) {
      const labels = {
        film: 'Film',
        movie: 'Film',
        artwork: 'Artwork',
        painting: 'Painting',
        sculpture: 'Sculpture',
        tv: 'TV Series',
        tv_series: 'TV Series',
        animation: 'Animation',
        documentary: 'Documentary'
      };
      return labels[type] || type || '';
    }
  }

  // ============================================
  // GLOBAL INSTANCE & API
  // ============================================

  // Create singleton instance
  const modalInstance = new DisambiguationModal();

  /**
   * Open disambiguation modal with similar works search
   * @param {string} originalQuery - The original search query
   * @param {Object} options - Options { currentWorkId }
   */
  async function openDisambiguationModal(originalQuery, options = {}) {
    const apiBase = window.API_BASE || 'http://localhost:8000/api';

    // Initialize and show loading
    modalInstance.init();
    modalInstance.modalEl.classList.add('active');
    document.body.style.overflow = 'hidden';
    modalInstance.showLoading();

    try {
      // Search for similar works
      const searchUrl = `${apiBase}/core/works/?search=${encodeURIComponent(originalQuery)}&limit=5`;
      const response = await fetch(searchUrl, {
        method: 'GET',
        headers: { 'Accept': 'application/json' }
      });

      if (!response.ok) {
        throw new Error(`Search failed: ${response.status}`);
      }

      const data = await response.json();
      let works = data.works || [];

      // Filter out the current work if provided
      if (options.currentWorkId) {
        works = works.filter(w => w.id !== options.currentWorkId);
      }

      // Take top 3
      const similarWorks = works.slice(0, 3);

      if (DEBUG) console.log('[Disambiguation] Found', similarWorks.length, 'similar works');

      // Show modal with results
      modalInstance.show(originalQuery, similarWorks, options);

    } catch (error) {
      console.error('[Disambiguation] Search error:', error);
      // Show form directly on error
      modalInstance.originalQuery = originalQuery;
      modalInstance.similarWorks = [];
      modalInstance.currentWorkId = options.currentWorkId || null;
      modalInstance.showFollowUpForm();
    }
  }

  // Expose globally
  window.DisambiguationModal = modalInstance;
  window.openDisambiguationModal = openDisambiguationModal;

  if (DEBUG) console.log('[Disambiguation] Module loaded');
})();
